      SUBROUTINE UPMARKC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER         IADR, IADRM, ICODE, IDATA, IS, J, NUPS      EXTERNAL        IDATAC      IF (ALIGN) THEN        IR = INT(DATA(I+2)) + 1        IADR = I + IPTOJ(4)        NUPS = IDATA(IADR)         IF (NUPS .NE. 0) THEN          DO 80 NAL = 1, NUPS          IF (NAL .GT. 10) THEN            WRITE (NOUT,9001) 9001       FORMAT (' *** TOO MANY NESTED MISALIGNMENTS')            FLUSHL = .TRUE.            GO TO 200          ENDIF          TYPEC = 8          IADRM = IADR + 1 + NUPS - NAL          NMIS = IDATA(IADRM)          IS = ISTOR(NMIS)          ICODE = INT(DATA(IS+7))          LFM = ICODE/100          DO 60 J = 1, 25   60     IPTOJB(J) = IPTOJ(J)          CALL SKETCH(NMIS)          IF (LFM .GE. 1) THEN            LXRAN = LFM .EQ. 2            IF (NV3 .GE. 1) THEN              CALL DERIVE            ELSE              CALL ELICIT              IF (.NOT. LSTEPN) THEN                CALL POSTER                CALL MPRINT              ENDIF            ENDIF            IF (FLUSHL) GO TO 200            IF (TYPE .LE. 0) GO TO 200          ENDIF          DO 70 J = 1, 25   70     IPTOJ(J) = IPTOJB(J)   80     CONTINUE        ENDIF      ENDIFC  200 RETURN      END